-- Create "workflow_settings" table
CREATE TABLE `workflow_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `content_types` json NULL, `lock_minutes` bigint NOT NULL DEFAULT 30, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "workflow_states" table
CREATE TABLE `workflow_states` (`id` int unsigned NOT NULL AUTO_INCREMENT, `machine_name` varchar(64) NOT NULL, `label` varchar(128) NOT NULL, `published` bool NOT NULL DEFAULT false, `color` varchar(16) NOT NULL DEFAULT 'gray', `initial` bool NOT NULL DEFAULT false, `weight` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`), UNIQUE INDEX `workflow_states_machine_name` (`machine_name`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "workflow_transitions" table
CREATE TABLE `workflow_transitions` (`id` int unsigned NOT NULL AUTO_INCREMENT, `from_states` json NOT NULL, `to_state` varchar(64) NOT NULL, `label` varchar(128) NOT NULL, `roles` json NOT NULL, `comment` varchar(16) NOT NULL DEFAULT 'optional', `weight` bigint NOT NULL DEFAULT 0, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "workflow_history" table
CREATE TABLE `workflow_history` (`id` int unsigned NOT NULL AUTO_INCREMENT, `from_state` varchar(64) NOT NULL, `to_state` varchar(64) NOT NULL, `uid` int unsigned NOT NULL DEFAULT 0, `comment` text NOT NULL, `created_at` datetime NOT NULL, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `workflow_history_nid` (`nid`, `created_at`), CONSTRAINT `workflow_history_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "workflow_locks" table
CREATE TABLE `workflow_locks` (`id` int unsigned NOT NULL AUTO_INCREMENT, `uid` int unsigned NOT NULL, `locked_at` datetime NOT NULL, `touched_at` datetime NOT NULL, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `workflow_locks_nid` (`nid`), CONSTRAINT `workflow_locks_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "workflow_node_states" table
CREATE TABLE `workflow_node_states` (`id` int unsigned NOT NULL AUTO_INCREMENT, `state` varchar(64) NOT NULL, `changed_at` datetime NOT NULL, `changed_by` int unsigned NOT NULL DEFAULT 0, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `workflow_node_states_nid` (`nid`), INDEX `workflow_node_states_state` (`state`, `changed_at`), CONSTRAINT `workflow_node_states_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
